// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, string(abi.encodePacked("N")), string(abi.encodePacked("S"))); }

    function testFuzz_property(address attackerFactory, uint256 burnAmount) public {
        vm.assume(attackerFactory != address(0));

        vm.deal(address(this), 1 ether);
        vm.prank(attackerFactory);
        Attacker atk = new Attacker(c);

        vm.deal(address(atk), 1 ether);

        bool ok;
        try atk.doBurn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == address(this));
    }
}

contract Attacker {
    ERCDDAToken c;
    constructor(ERCDDAToken _c) {
        c = _c;
    }
    function doBurn(uint256 amount) external {
        (bool s, ) = address(c).call(abi.encodeWithSignature("owned()"));
        (bool s2, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", amount));
        require(s || s2 ? true : true);
    }
}
